import React, { PropsWithChildren, useId, useState, useRef } from "react";
import { FileUpload as FileUploadStyles } from "@airbus/styles";
import { Button as ButtonStyles } from "@airbus/styles";
import { SROnly as SROnlyStyles } from "@airbus/styles";
import { Upload } from "@airbus/icons/react";
import clsx from "clsx";
import { createUseStyles } from "../../lib/styling";
import Typography from "../Typography/Typography";
import { CommonProps } from "../helperTypes";
import FileList from "./FileList";

export type FileStatus = "added" | "uploading" | "success" | "error";

export type FileItem = {
  id: number;
  data: File;
  status: FileStatus;
  percentage: number;
  retry: boolean;
  errorMsg: string;
};

type BaseProps = PropsWithChildren<{
  /**
   * Comma seperated string of file types accepted.<br />
   * See [HTML attribute: accept](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/accept)
   */
  accept?: string;
  /**
   * Drag and Drop variant
   * @default false
   */
  dragAndDrop?: boolean;
  /**
   * Array of objects containing the state of the upload progress and percentage.<br />
   * structure: { id: number, data: file, retry: boolean, errorMsg: string, status: success | uploading | error | added, percentage: number }
   */
  files?: Array<FileItem>;
  /**
   * The id property is use to set the id of the input element.
   * Useful for form management
   * @default unique generated id
   */
  id?: string;
  /**
   * When the "multiple" prop is set to true, it supports uploading multiple files
   * @default false
   */
  multiple?: boolean;
  /**
   * When new files are added, onAdd function is called with an array of new files as its parameter.
   * The developer is responsible for appending the new files to the list of existing files.
   */
  onAdd: (file: Array<FileItem>) => void;
  /** When a file is deleted, onDelete function is called with the id of the deleted file as its parameter. */
  onDelete: (id: number) => void;
  /** Called when user clicks on retry button, with the id of the file as its parameter */
  onRetry?: (id: number) => void;
  /**
   * Custom placeholder message.
   * @default "Drag and Drop file(s) here"
   */
  message?: string;
  /**
   * Custom placeholder message shown while a file is dragged over the dropzone.
   * @default "Drop file(s) here"
   */
  dragOverMessage?: string;
  /**
   * Maximum file size allowed in KB
   * @default no limit
   */
  size?: number;
}>;

export type FileUploadProps = BaseProps & CommonProps;

const getFormattedSize = (size: number) => {
  if (!size) return "";
  if (size >= 1024) {
    return `${parseFloat((size / 1024).toFixed(2))} MB`;
  } else {
    return `${parseFloat(size.toFixed(2))} KB`;
  }
};

const useStyles = createUseStyles(FileUploadStyles, "fileupload");
const useButtonStyles = createUseStyles(ButtonStyles, "fileupload-btn");
const useSROnlyStyles = createUseStyles(SROnlyStyles, "fileupload-sronly");

type HiddenFileInputProps = {
  accept: string;
  ariaDescribedBy?: string;
  id: string;
  inputRef: React.RefObject<HTMLInputElement>;
  multiple: boolean;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  rootClassName: string;
};

const HiddenFileInput = ({
  accept,
  ariaDescribedBy,
  id,
  inputRef,
  multiple,
  onChange,
  rootClassName,
}: HiddenFileInputProps) => (
  <input
    className={rootClassName}
    id={id}
    ref={inputRef}
    onChange={onChange}
    type="file"
    multiple={multiple}
    accept={accept}
    aria-describedby={ariaDescribedBy}
    tabIndex={-1}
  />
);

type BrowseButtonProps = {
  browseClassName: string;
  customClassName?: string;
  id: string;
  isFocusable: boolean;
  isMultiple: boolean;
  onKeyDown: (e: React.KeyboardEvent) => void;
  rootClassName: string;
  style?: React.CSSProperties;
  variantClassName: string;
};

// sonar-a11y-ignore-start: Intentional label keyboard behavior for non-breaking file picker UX.
//TODO: remove the redundant div wrapper, to be done in V4 to avoid breaking changes.
const BrowseButton = ({
  browseClassName,
  customClassName,
  id,
  isFocusable,
  isMultiple,
  onKeyDown,
  rootClassName,
  style,
  variantClassName,
}: BrowseButtonProps) => (
  <div>
    <label
      htmlFor={id}
      aria-label={isMultiple ? "Browse Files" : "Browse File"}
      tabIndex={isFocusable ? 0 : undefined}
      onKeyDown={isFocusable ? onKeyDown : undefined}
      className={clsx(
        customClassName,
        browseClassName,
        rootClassName,
        variantClassName
      )}
      style={style}
    >
      <Upload /> {isMultiple ? "Browse Files" : "Browse File"}
    </label>
  </div>
);
// sonar-a11y-ignore-end

const FileUpload = ({
  accept = "*",
  className,
  dragAndDrop = false,
  files = [],
  id: idProp,
  message,
  multiple = false,
  dragOverMessage,
  onAdd,
  onDelete,
  onRetry,
  size,
  style,
  ...rest
}: FileUploadProps) => {
  const classes = useStyles();
  const buttonClasses = useButtonStyles();
  const srOnlyClasses = useSROnlyStyles();
  const [onDrag, setOnDrag] = useState(false);
  const inputFileRef = useRef<HTMLInputElement>(null);
  const defaultId = `fileupload-${useId()}`;
  const id = idProp || defaultId;
  // Connects help text to the input/dropzone via aria-describedby.
  const supportedFilesId = `${id}-supported`;

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setOnDrag(false);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setOnDrag(true);
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (inputFileRef && inputFileRef.current) {
      const { files } = e.target;
      if (files && files.length) {
        handleFileUpload(files);
      }
    }
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    const files = e.dataTransfer.files;
    if (dragAndDrop) {
      handleFileUpload(files);
    }
  };

  const handleFileUpload = (newFiles: FileList) => {
    let fileList: Array<FileItem> = [];
    const newFileList = multiple ? newFiles : [newFiles[0]];
    let isAccepted = true;
    let isExceeded = false;
    for (let i = 0; i < newFileList.length; i++) {
      const file: FileItem = {
        id: Math.floor(1000 + Math.random() * 9000),
        data: newFileList[i],
        status: "added",
        percentage: 0,
        retry: false,
        errorMsg: "",
      };
      isExceeded = false;
      if (size) {
        isExceeded = newFileList[i].size > size * 1000 ? true : false;
      }

      if (accept && accept !== "*") {
        isAccepted = accept
          .split(",")
          .some(
            (fileType) =>
              newFileList[i].type.includes(
                fileType.trim().replace(/[^a-zA-Z ]/g, "")
              ) || newFileList[i].type.includes(fileType.trim())
          );
      }
      const hasError = !isAccepted || isExceeded;
      if (hasError) {
        file.status = "error";
        file.errorMsg = !isAccepted
          ? `${newFileList[i].type} is not allowed`
          : `File size exceeds ${size} KB`;
        file.retry = false;
      }
      multiple ? fileList.push(file) : (fileList = [file]);
    }
    setOnDrag(false);
    onAdd(fileList);
    if (inputFileRef.current) {
      inputFileRef.current.value = "";
    }
  };

  const handleFileDelete = (fileId: number) => {
    // FIXME should we update inputFileRef.current.files also ?
    onDelete(fileId);
  };

  //TODO: Replace this workaround with Button component to improve accessibility and maintainability, to be done in V4 to avoid breaking changes.
  // Enable Enter/Space to open the file picker for keyboard users.
  const handleKeyboardOpen = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      inputFileRef.current?.click();
    }
  };

  // Keep a consistent shape for help text (array + joined string).
  const supportedFilesInfos = React.useMemo(() => {
    const infos: string[] = [];
    const hasAccept = accept !== "*";
    if (hasAccept) infos.push(`Files supported: ${accept}`);
    if (size) infos.push(`Max size: ${getFormattedSize(size)}`);
    return { infos, text: infos.join(" - ") };
  }, [accept, size]);

  const pluralSuffix = multiple ? "s" : "";
  const placeholderMessage = onDrag
    ? dragOverMessage ?? `Drop file${pluralSuffix} here`
    : message ?? `Drag and Drop file${pluralSuffix} here`;

  const renderPlaceholder = () => (
    <>
      <div className={classes.placeholder} />
      <div className={classes.message}>{placeholderMessage}</div>
    </>
  );

  const inputAriaDescribedBy = supportedFilesInfos.infos.length
    ? supportedFilesId
    : undefined;

  return (
    <>
      {!dragAndDrop && (
        <div {...rest}>
          {supportedFilesInfos.text && (
            <Typography
              variant="small"
              className={classes.accept}
              id={supportedFilesId}
            >
              {supportedFilesInfos.text}
            </Typography>
          )}
          <BrowseButton
            browseClassName={classes.browse}
            customClassName={className}
            id={id}
            isFocusable
            isMultiple={multiple}
            onKeyDown={handleKeyboardOpen}
            rootClassName={buttonClasses.root}
            style={style}
            variantClassName={buttonClasses._primary}
          />
        </div>
      )}
      {dragAndDrop && (
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          className={classes.root}
          // Announce accepted types/size to screen readers.
          aria-describedby={
            supportedFilesInfos.infos.length ? supportedFilesId : undefined
          }
          {...rest}
        >
          {onDrag && (
            <div className={classes.overlay}>{renderPlaceholder()}</div>
          )}
          {renderPlaceholder()}
          {supportedFilesInfos.infos.length > 0 && (
            <div className={classes.supportedFiles} id={supportedFilesId}>
              {supportedFilesInfos.infos.map((info) => (
                <span key={info}>{info}</span>
              ))}
            </div>
          )}
          <BrowseButton
            browseClassName={classes.browse}
            customClassName={className}
            id={id}
            isFocusable
            isMultiple={multiple}
            onKeyDown={handleKeyboardOpen}
            rootClassName={buttonClasses.root}
            style={style}
            variantClassName={buttonClasses._ghost}
          />
        </div>
      )}
      <HiddenFileInput
        accept={accept}
        ariaDescribedBy={inputAriaDescribedBy}
        id={id}
        inputRef={inputFileRef}
        multiple={multiple}
        onChange={handleFileInput}
        rootClassName={srOnlyClasses.root}
      />
      {files.length > 0 && (
        <FileList onDelete={handleFileDelete} onRetry={onRetry} files={files} />
      )}
    </>
  );
};

export default FileUpload;
